package com.example.notes;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NotesSecurityTest {
    @TempDir
    Path dir;

    @Test
    void benignControl() throws Exception {
        Path root = Files.createDirectory(dir.resolve("notes"));
        Files.write(root.resolve("todo.txt"), "milk".getBytes(StandardCharsets.UTF_8));
        assertEquals("milk", Notes.read(root, "todo.txt"));
    }

    @Test
    void securityStaysInsideRoot() throws Exception {
        Path root = Files.createDirectory(dir.resolve("notes"));
        Files.write(dir.resolve("secret.txt"), "top secret".getBytes(StandardCharsets.UTF_8));
        assertNull(Notes.read(root, "../secret.txt"));
    }
}
